package jo.orbitfarm.advisor.alert;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="farmer_alert") public class FarmerAlertEntity{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="farmer_id",nullable=false)private Long farmerId;@Column(name="farm_id")private Long farmId;@Column(name="alert_type",nullable=false,length=40)private String alertType;@Column(nullable=false,length=20)private String severity;@Column(nullable=false,length=180)private String title;@Column(nullable=false,length=1000)private String message;@Column(name="data_source",length=80)private String dataSource;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="read_at")private Instant readAt;
 protected FarmerAlertEntity(){}public FarmerAlertEntity(Long farmerId,Long farmId,String type,String severity,String title,String message,String source){this.farmerId=farmerId;this.farmId=farmId;this.alertType=type;this.severity=severity;this.title=title;this.message=message;this.dataSource=source;this.createdAt=Instant.now();}
 public Long getId(){return id;}public Long getFarmerId(){return farmerId;}public Long getFarmId(){return farmId;}public String getAlertType(){return alertType;}public String getSeverity(){return severity;}public String getTitle(){return title;}public String getMessage(){return message;}public String getDataSource(){return dataSource;}public Instant getCreatedAt(){return createdAt;}public Instant getReadAt(){return readAt;}public void markRead(){if(readAt==null)readAt=Instant.now();}
}
